-- ==============================================================================
-- BASIS DATA RESMI SIAKAD SMK NEGERI 9 KABUPATEN TANGERANG
-- NAMA DATABASE : db_smkn9
-- ENGINE        : InnoDB | CHARSET : utf8mb4 | COLLATION : utf8mb4_unicode_ci
-- TARGET        : MySQL 8.0+ / MariaDB 10.4+ / Laragon phpMyAdmin
-- ==============================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+07:00';

CREATE DATABASE IF NOT EXISTS `db_smkn9` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_smkn9`;

DROP TABLE IF EXISTS `log_audit`;
DROP TABLE IF EXISTS `log_event`;
DROP TABLE IF EXISTS `event_sekolah`;
DROP TABLE IF EXISTS `kategori_event`;
DROP TABLE IF EXISTS `kehadiran_siswa`;
DROP TABLE IF EXISTS `nilai_siswa`;
DROP TABLE IF EXISTS `jadwal_pelajaran`;
DROP TABLE IF EXISTS `penugasan_guru`;
DROP TABLE IF EXISTS `kurikulum_mapel`;
DROP TABLE IF EXISTS `mata_pelajaran`;
DROP TABLE IF EXISTS `pengurus_osis`;
DROP TABLE IF EXISTS `riwayat_kelas_siswa`;
DROP TABLE IF EXISTS `penugasan_wali_kelas`;
DROP TABLE IF EXISTS `siswa`;
DROP TABLE IF EXISTS `kelas`;
DROP TABLE IF EXISTS `jurusan`;
DROP TABLE IF EXISTS `guru`;
DROP TABLE IF EXISTS `semester`;
DROP TABLE IF EXISTS `tahun_ajaran`;
DROP TABLE IF EXISTS `pengguna`;
DROP TABLE IF EXISTS `peran`;

-- ------------------------------------------------------------------------------
-- 1. TABEL: peran
-- ------------------------------------------------------------------------------
CREATE TABLE `peran` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `kode_peran` VARCHAR(30) NOT NULL UNIQUE COMMENT 'kesiswaan, kaprog, wali_kelas, siswa, osis',
    `nama_peran` VARCHAR(50) NOT NULL,
    `deskripsi` VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 2. TABEL: pengguna (Login dengan NIS untuk Siswa, NUPTK untuk Guru)
-- ------------------------------------------------------------------------------
CREATE TABLE `pengguna` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nomor_induk` VARCHAR(30) NOT NULL UNIQUE COMMENT 'NIS untuk siswa, NUPTK untuk guru/staff',
    `email` VARCHAR(100) NULL,
    `kata_sandi` VARCHAR(255) NOT NULL,
    `id_peran` INT NOT NULL,
    `nama_lengkap` VARCHAR(100) NOT NULL,
    `nomor_telepon` VARCHAR(20) NULL,
    `foto_profil` VARCHAR(255) NULL DEFAULT 'avatar_default.png',
    `apakah_aktif` TINYINT(1) NOT NULL DEFAULT 1,
    `dibuat_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `diperbarui_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_pengguna_peran` FOREIGN KEY (`id_peran`) REFERENCES `peran` (`id`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 3. TABEL: tahun_ajaran & semester
-- ------------------------------------------------------------------------------
CREATE TABLE `tahun_ajaran` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `kode_tahun` VARCHAR(15) NOT NULL UNIQUE COMMENT 'Contoh: 2026-2027',
    `nama_tahun` VARCHAR(30) NOT NULL COMMENT 'Tahun Ajaran 2026/2027',
    `apakah_aktif` TINYINT(1) NOT NULL DEFAULT 0,
    `tanggal_mulai` DATE NOT NULL,
    `tanggal_selesai` DATE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `semester` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_tahun_ajaran` INT NOT NULL,
    `jenis_semester` ENUM('ganjil', 'genap') NOT NULL,
    `apakah_aktif` TINYINT(1) NOT NULL DEFAULT 0,
    `tanggal_mulai` DATE NOT NULL,
    `tanggal_selesai` DATE NOT NULL,
    UNIQUE KEY `uk_semester_tahun_jenis` (`id_tahun_ajaran`, `jenis_semester`),
    CONSTRAINT `fk_semester_tahun_ajaran` FOREIGN KEY (`id_tahun_ajaran`) REFERENCES `tahun_ajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 4. TABEL: jurusan (6 Konsentrasi Keahlian Resmi)
-- ------------------------------------------------------------------------------
CREATE TABLE `jurusan` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `kode_jurusan` VARCHAR(20) NOT NULL UNIQUE COMMENT 'TKJ, DKV, AKC, FKK, MPLB, TBSM',
    `nama_jurusan` VARCHAR(100) NOT NULL,
    `id_guru_kaprog` INT NULL COMMENT 'Kepala Program Keahlian',
    `kode_lab` VARCHAR(50) NULL COMMENT 'Kode Lab/Bengkel Utama (Labkom 001, Bengkel 001, dll)',
    `deskripsi` TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 5. TABEL: guru (Data Lengkap 98 Guru/Tenaga Pendidik)
-- ------------------------------------------------------------------------------
CREATE TABLE `guru` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_pengguna` INT NULL UNIQUE COMMENT 'Terhubung ke akun login pengguna',
    `nuptk` VARCHAR(30) NOT NULL UNIQUE COMMENT 'Nomor Unik Pendidik dan Tenaga Kependidikan',
    `nip` VARCHAR(30) NULL COMMENT 'NIP ASN (jika ada)',
    `nama_lengkap` VARCHAR(100) NOT NULL,
    `jenis_kelamin` ENUM('L', 'P') NOT NULL DEFAULT 'L',
    `tempat_lahir` VARCHAR(50) NULL DEFAULT 'Tangerang',
    `tanggal_lahir` DATE NULL DEFAULT '1985-05-15',
    `agama` VARCHAR(20) NULL DEFAULT 'Islam',
    `nomor_telepon` VARCHAR(20) NULL,
    `email` VARCHAR(100) NULL,
    `alamat` TEXT NULL,
    `provinsi` VARCHAR(50) NULL DEFAULT 'Banten',
    `kabupaten` VARCHAR(50) NULL DEFAULT 'Kabupaten Tangerang',
    `kode_pos` VARCHAR(10) NULL DEFAULT '15710',
    `pendidikan_terakhir` VARCHAR(50) NULL DEFAULT 'S1 Kependidikan',
    `npwp` VARCHAR(30) NULL,
    `id_jurusan` INT NULL COMMENT 'Jurusan homebase guru kejuruan',
    `mapel_utama` VARCHAR(100) NULL,
    `jabatan_tugas` VARCHAR(50) NULL DEFAULT 'Guru Pengajar',
    `apakah_aktif` TINYINT(1) NOT NULL DEFAULT 1,
    CONSTRAINT `fk_guru_pengguna` FOREIGN KEY (`id_pengguna`) REFERENCES `pengguna` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_guru_jurusan` FOREIGN KEY (`id_jurusan`) REFERENCES `jurusan` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 6. TABEL: kelas (36 Kelas: 2 rombel per tingkat di 6 jurusan)
-- ------------------------------------------------------------------------------
CREATE TABLE `kelas` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_jurusan` INT NOT NULL,
    `tingkat` TINYINT NOT NULL COMMENT '10, 11, atau 12',
    `nomor_rombel` TINYINT UNSIGNED NOT NULL,
    `nama_kelas` VARCHAR(50) NOT NULL UNIQUE COMMENT 'Contoh: 10 TKJ 1, 11 DKV 1',
    UNIQUE KEY `uk_kelas_jurusan_tingkat_rombel` (`id_jurusan`, `tingkat`, `nomor_rombel`),
    CONSTRAINT `fk_kelas_jurusan` FOREIGN KEY (`id_jurusan`) REFERENCES `jurusan` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `penugasan_wali_kelas` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_guru` INT NOT NULL,
    `id_kelas` INT NOT NULL,
    `id_tahun_ajaran` INT NOT NULL,
    `apakah_aktif` TINYINT(1) NOT NULL DEFAULT 1,
    `tanggal_mulai_tugas` DATE NOT NULL DEFAULT (CURRENT_DATE),
    `dibuat_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_wali_kelas_periode` (`id_kelas`, `id_tahun_ajaran`),
    CONSTRAINT `fk_pwk_guru` FOREIGN KEY (`id_guru`) REFERENCES `guru` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_pwk_kelas` FOREIGN KEY (`id_kelas`) REFERENCES `kelas` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_pwk_tahun_ajaran` FOREIGN KEY (`id_tahun_ajaran`) REFERENCES `tahun_ajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 8. TABEL: siswa (Data Lengkap 1.080 Siswa)
-- ------------------------------------------------------------------------------
CREATE TABLE `siswa` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_pengguna` INT NULL UNIQUE COMMENT 'Akun login portal siswa',
    `nis` VARCHAR(20) NOT NULL UNIQUE COMMENT 'Nomor Induk Siswa Sekolah',
    `nisn` VARCHAR(20) NULL UNIQUE COMMENT 'Nomor Induk Siswa Nasional',
    `nama_lengkap` VARCHAR(100) NOT NULL,
    `jenis_kelamin` ENUM('L', 'P') NOT NULL DEFAULT 'L',
    `tempat_lahir` VARCHAR(50) NULL DEFAULT 'Tangerang',
    `tanggal_lahir` DATE NULL,
    `agama` VARCHAR(20) NULL DEFAULT 'Islam',
    `alamat` TEXT NULL,
    `provinsi` VARCHAR(50) NULL DEFAULT 'Banten',
    `kabupaten` VARCHAR(50) NULL DEFAULT 'Kabupaten Tangerang',
    `kode_pos` VARCHAR(10) NULL DEFAULT '15710',
    `nomor_telepon` VARCHAR(20) NULL,
    `nama_ayah` VARCHAR(100) NULL,
    `nama_ibu` VARCHAR(100) NULL,
    `pekerjaan_ortu` VARCHAR(100) NULL DEFAULT 'Wiraswasta',
    `telepon_orang_tua` VARCHAR(20) NULL,
    `id_jurusan` INT NOT NULL,
    `tahun_masuk` YEAR NOT NULL,
    `foto` VARCHAR(255) NULL DEFAULT 'foto_siswa_default.png',
    `status_siswa` ENUM('aktif', 'lulus', 'mutasi', 'keluar') NOT NULL DEFAULT 'aktif',
    CONSTRAINT `fk_siswa_pengguna` FOREIGN KEY (`id_pengguna`) REFERENCES `pengguna` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_siswa_jurusan` FOREIGN KEY (`id_jurusan`) REFERENCES `jurusan` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `riwayat_kelas_siswa` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_siswa` INT NOT NULL,
    `id_kelas` INT NOT NULL,
    `id_tahun_ajaran` INT NOT NULL,
    `status_penempatan` ENUM('aktif', 'naik', 'tinggal', 'lulus', 'pindah') NOT NULL DEFAULT 'aktif',
    `didaftarkan_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_siswa_tahun_ajaran` (`id_siswa`, `id_tahun_ajaran`),
    CONSTRAINT `fk_rks_siswa` FOREIGN KEY (`id_siswa`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_rks_kelas` FOREIGN KEY (`id_kelas`) REFERENCES `kelas` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_rks_tahun_ajaran` FOREIGN KEY (`id_tahun_ajaran`) REFERENCES `tahun_ajaran` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pengurus_osis` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_siswa` INT NOT NULL,
    `jabatan` VARCHAR(100) NOT NULL COMMENT 'Ketua OSIS, Wakil Ketua, Sekretaris, Bendahara, Seksi Bidang',
    `periode` VARCHAR(30) NOT NULL DEFAULT '2026/2027',
    `status_aktif` TINYINT(1) NOT NULL DEFAULT 1,
    CONSTRAINT `fk_osis_siswa` FOREIGN KEY (`id_siswa`) REFERENCES `siswa` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `mata_pelajaran` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `kode_mapel` VARCHAR(20) NOT NULL UNIQUE,
    `nama_mapel` VARCHAR(100) NOT NULL,
    `kelompok_mapel` ENUM('umum', 'kejuruan', 'muatan_lokal') NOT NULL DEFAULT 'umum',
    `id_jurusan` INT NULL,
    CONSTRAINT `fk_mapel_jurusan` FOREIGN KEY (`id_jurusan`) REFERENCES `jurusan` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `kurikulum_mapel` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_tahun_ajaran` INT NOT NULL,
    `id_jurusan` INT NOT NULL,
    `tingkat` TINYINT UNSIGNED NOT NULL,
    `jenis_semester` ENUM('ganjil', 'genap') NOT NULL,
    `id_mapel` INT NOT NULL,
    `pertemuan_per_minggu` TINYINT UNSIGNED NOT NULL,
    UNIQUE KEY `uk_kurikulum_mapel_semester` (`id_tahun_ajaran`, `id_jurusan`, `tingkat`, `jenis_semester`, `id_mapel`),
    CONSTRAINT `fk_kurikulum_tahun_ajaran` FOREIGN KEY (`id_tahun_ajaran`) REFERENCES `tahun_ajaran` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_kurikulum_jurusan` FOREIGN KEY (`id_jurusan`) REFERENCES `jurusan` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_kurikulum_mapel` FOREIGN KEY (`id_mapel`) REFERENCES `mata_pelajaran` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `penugasan_guru` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_tahun_ajaran` INT NOT NULL,
    `id_semester` INT NOT NULL,
    `id_guru` INT NOT NULL,
    `id_mapel` INT NOT NULL,
    `id_kelas` INT NOT NULL,
    UNIQUE KEY `uk_tugas_mengajar` (`id_tahun_ajaran`, `id_semester`, `id_guru`, `id_mapel`, `id_kelas`),
    CONSTRAINT `fk_pg_tahun_ajaran` FOREIGN KEY (`id_tahun_ajaran`) REFERENCES `tahun_ajaran` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_pg_semester` FOREIGN KEY (`id_semester`) REFERENCES `semester` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_pg_guru` FOREIGN KEY (`id_guru`) REFERENCES `guru` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_pg_mapel` FOREIGN KEY (`id_mapel`) REFERENCES `mata_pelajaran` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_pg_kelas` FOREIGN KEY (`id_kelas`) REFERENCES `kelas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `jadwal_pelajaran` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_penugasan_guru` INT NOT NULL,
    `hari` ENUM('Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat') NOT NULL,
    `jam_mulai` TIME NOT NULL,
    `jam_selesai` TIME NOT NULL,
    `ruangan` VARCHAR(50) NOT NULL DEFAULT 'Ruang Teori 101',
    `apakah_lab` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1 jika menggunakan lab/bengkel',
    CONSTRAINT `fk_jp_penugasan_guru` FOREIGN KEY (`id_penugasan_guru`) REFERENCES `penugasan_guru` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `nilai_siswa` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_siswa` INT NOT NULL,
    `id_penugasan_guru` INT NOT NULL,
    `id_semester` INT NOT NULL,
    `nilai_tugas` DECIMAL(5, 2) NULL DEFAULT 0.00,
    `nilai_uts` DECIMAL(5, 2) NULL DEFAULT 0.00,
    `nilai_uas` DECIMAL(5, 2) NULL DEFAULT 0.00,
    `nilai_praktik` DECIMAL(5, 2) NULL DEFAULT 0.00,
    `nilai_akhir` DECIMAL(5, 2) NULL DEFAULT 0.00,
    `predikat_huruf` ENUM('A', 'B', 'C', 'D', 'E') NULL,
    `status_nilai` ENUM('draf', 'final') NOT NULL DEFAULT 'final',
    `disahkan_oleh` INT NULL,
    `disahkan_pada` TIMESTAMP NULL,
    `diperbarui_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_nilai_siswa_mapel_semester` (`id_siswa`, `id_penugasan_guru`, `id_semester`),
    CONSTRAINT `fk_ns_siswa` FOREIGN KEY (`id_siswa`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_ns_penugasan` FOREIGN KEY (`id_penugasan_guru`) REFERENCES `penugasan_guru` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_ns_semester` FOREIGN KEY (`id_semester`) REFERENCES `semester` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `kehadiran_siswa` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_siswa` INT NOT NULL,
    `id_semester` INT NOT NULL,
    `sakit` INT NOT NULL DEFAULT 0,
    `izin` INT NOT NULL DEFAULT 0,
    `alfa` INT NOT NULL DEFAULT 0,
    `catatan` VARCHAR(255) NULL,
    `diperbarui_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY `uk_kehadiran_siswa_semester` (`id_siswa`, `id_semester`),
    CONSTRAINT `fk_kehadiran_siswa` FOREIGN KEY (`id_siswa`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_kehadiran_semester` FOREIGN KEY (`id_semester`) REFERENCES `semester` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `kategori_event` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama_kategori` VARCHAR(50) NOT NULL,
    `slug` VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `event_sekolah` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `judul` VARCHAR(150) NOT NULL,
    `slug` VARCHAR(180) NOT NULL UNIQUE,
    `id_kategori` INT NOT NULL,
    `deskripsi` LONGTEXT NOT NULL,
    `lokasi` VARCHAR(100) NOT NULL DEFAULT 'SMKN 9 Tangerang',
    `waktu_mulai` DATETIME NOT NULL,
    `waktu_selesai` DATETIME NOT NULL,
    `foto_poster` VARCHAR(255) NULL,
    `penyelenggara` VARCHAR(100) NOT NULL DEFAULT 'OSIS SMKN 9 Tangerang',
    `status` ENUM('draf', 'menunggu_persetujuan', 'dipublikasikan', 'diarsipkan') NOT NULL DEFAULT 'dipublikasikan',
    `dibuat_oleh_id_pengguna` INT NOT NULL,
    `disetujui_oleh_id_pengguna` INT NULL,
    `disetujui_pada` TIMESTAMP NULL,
    `alasan_penolakan` TEXT NULL,
    `dibuat_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `diperbarui_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `fk_es_kategori` FOREIGN KEY (`id_kategori`) REFERENCES `kategori_event` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_es_pembuat` FOREIGN KEY (`dibuat_oleh_id_pengguna`) REFERENCES `pengguna` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `log_event` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `id_event` INT NOT NULL,
    `id_pengguna_pelaku` INT NOT NULL,
    `aksi` VARCHAR(50) NOT NULL,
    `catatan` TEXT NULL,
    `dibuat_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_log_event_event` FOREIGN KEY (`id_event`) REFERENCES `event_sekolah` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_log_event_pengguna` FOREIGN KEY (`id_pengguna_pelaku`) REFERENCES `pengguna` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `log_audit` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `id_pengguna` INT NULL,
    `aksi` VARCHAR(50) NOT NULL,
    `modul` VARCHAR(50) NOT NULL,
    `id_data` INT NULL,
    `nilai_lama` JSON NULL,
    `nilai_baru` JSON NULL,
    `alamat_ip` VARCHAR(45) NOT NULL DEFAULT '0.0.0.0',
    `agen_pengguna` VARCHAR(255) NULL,
    `dibuat_pada` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ==============================================================================
-- SEEDING DATA DUMMY
-- ==============================================================================













-- Jadwal KBM: 5 JP x 90 menit per hari, Senin-Jumat; istirahat 10:00-10:30 dan 12:00-12:30.
-- Penugasan guru dipakai ulang untuk sesi mapel yang sama pada kelas dan semester yang sama.






-- ------------------------------------------------------------------------------
-- Relasi Kaprog Jurusan ke Guru (Setelah data guru terisi lengkap)
-- ------------------------------------------------------------------------------
ALTER TABLE `jurusan` ADD CONSTRAINT `fk_jurusan_guru_kaprog` FOREIGN KEY (`id_guru_kaprog`) REFERENCES `guru` (`id`) ON DELETE SET NULL;

SET FOREIGN_KEY_CHECKS = 1;
-- ======================== SELESAI ========================
