INSERT INTO `jurusan` (`id`, `kode_jurusan`, `nama_jurusan`, `id_guru_kaprog`, `kode_lab`, `deskripsi`) VALUES
(1, 'TKJ', 'Teknik Komputer Jaringan', 4, 'Labkom 001', 'Penguasaan instalasi jaringan, administrasi server, fiber optic, dan cybersecurity.'),
(2, 'DKV', 'Desain Komunikasi Visual', 3, 'Lab Desain 001', 'Pengembangan desain grafis, ilustrasi digital, UI/UX, dan videografi kreatif.'),
(3, 'AKC', 'Asisten Perawatan dan Caregiver', 5, 'Lab Keperawatan 001', 'Pelayanan dasar keperawatan, homecare, pendampingan lansia, dan sanitasi kesehatan.'),
(4, 'FKK', 'Farmasi Klinik dan Komunitas', 6, 'Lab Farmasi 001', 'Teknik peracikan obat, farmakologi dasar, manajemen apotek, dan dispensing obat.'),
(5, 'MPLB', 'Manajemen Perkantoran dan Layanan Bisnis', 7, NULL, 'Pengelolaan administrasi modern, kearsipan digital, customer service, dan korespondensi bisnis.'),
(6, 'TBSM', 'Teknik dan Bisnis Sepeda Motor', 8, 'Bengkel 001', 'Perawatan mesin berkala, kelistrikan sepeda motor, injeksi EFI, dan wirausaha bengkel.');
