INSERT INTO `event_sekolah` (`id`, `judul`, `slug`, `id_kategori`, `deskripsi`, `lokasi`, `waktu_mulai`, `waktu_selesai`, `foto_poster`, `penyelenggara`, `status`, `dibuat_oleh_id_pengguna`, `disetujui_oleh_id_pengguna`, `disetujui_pada`, `alasan_penolakan`, `dibuat_pada`) VALUES
(1, 'Gebyar Dies Natalis & Gelar Karya Vokasi SMKN 9 Kabupaten Tangerang', 'gebyar-dies-natalis-smkn9-2026', 4, 'Pameran inovasi kejuruan TKJ, DKV, AKC, FKK, MPLB, dan TBSM menampilkan hasil karya siswa, bursa kerja khusus, dan pentas seni pelajar se-Kabupaten Tangerang.', 'Graha Utama SMKN 9 Kabupaten Tangerang', '2026-11-15 08:00:00', '2026-11-17 16:00:00', 'poster_dies_natalis_2026.jpg', 'OSIS SMKN 9 Kabupaten Tangerang', 'dipublikasikan', 5, 1, '2026-10-10 09:00:00', NULL, '2026-10-05 10:00:00'),
